css:
.aero-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Inter', Roboto, sans-serif;
    color: #c9d1d9;
}

.aero-sim-header {
    background: linear-gradient(135deg, #0d1b2a 0%, #1b2838 50%, #0d1b2a 100%);
    border: 1px solid #1c3a5e;
    border-radius: 12px;
    padding: 32px;
    margin-bottom: 24px;
    text-align: center;
    position: relative;
    overflow: hidden;
    box-shadow: 0 0 40px rgba(0,180,216,0.08);
}

.aero-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #00b4d8, #0077b6, #00b4d8);
}

.aero-sim-airline-badge {
    font-size: 0.85rem;
    color: #00b4d8;
    letter-spacing: 0.25em;
    text-transform: uppercase;
    margin-bottom: 8px;
    font-weight: 700;
}

.aero-sim-header h1 {
    font-size: 1.6rem;
    font-weight: 800;
    color: #e6f1ff;
    margin: 8px 0 6px;
    font-family: -apple-system, 'Inter', 'Segoe UI', sans-serif;
    letter-spacing: 0.02em;
}

.aero-sim-header p {
    color: #8b949e;
    font-size: 0.85rem;
    margin: 0;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-period-counter {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 12px 20px;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.95rem;
    color: #8b949e;
    font-weight: 600;
}

.aero-sim-round-name {
    margin-left: auto;
    font-weight: 700;
    color: #00b4d8;
    font-size: 0.82rem;
    background: rgba(0,180,216,0.1);
    border: 1px solid rgba(0,180,216,0.25);
    padding: 3px 12px;
    border-radius: 20px;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(165px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}

.aero-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 20px 16px;
    text-align: center;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.15s ease;
}

.aero-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00b4d8, #0077b6);
}

.aero-sim-kpi-card:hover {
    border-color: #2d4a6f;
    transform: translateY(-2px);
}

.aero-sim-kpi-primary {
    background: #0d1f35;
    border-color: #00b4d8;
}

.aero-sim-kpi-primary::before {
    background: linear-gradient(90deg, #00b4d8, #48cae4, #00b4d8);
    height: 3px;
}

.aero-sim-kpi-label {
    color: #9aa4b2;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 700;
    margin-bottom: 8px;
}

.aero-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 800;
    color: #00b4d8;
    line-height: 1.1;
    font-family: 'Courier New', ui-monospace, SFMono-Regular, monospace;
}

.aero-sim-kpi-sub {
    font-size: 0.62rem;
    color: #8b949e;
    margin-top: 6px;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 4px solid #0077b6;
    border-radius: 10px;
    padding: 22px 24px;
    margin-bottom: 24px;
}

.aero-sim-briefing-header {
    font-weight: 700;
    font-size: 0.85rem;
    color: #00b4d8;
    margin-bottom: 14px;
    display: flex;
    align-items: center;
    gap: 8px;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

.aero-sim-briefing-text {
    color: #c9d1d9;
    font-size: 0.85rem;
    line-height: 1.7;
    margin-bottom: 16px;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-route-panel {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    padding-top: 14px;
    border-top: 1px solid #1f2d3d;
}

.aero-sim-route-item {
    background: rgba(0,180,216,0.05);
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 10px 14px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    font-size: 0.72rem;
    color: #8b949e;
    flex: 1;
    min-width: 180px;
}

.aero-sim-route-info {
    font-weight: 800;
    font-size: 0.9rem;
    color: #48cae4;
}

.aero-sim-decisions-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-bottom: 24px;
}

.aero-sim-decisions-panel,
.aero-sim-results-panel {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 12px;
    padding: 24px;
}

.aero-sim-decisions-panel h3,
.aero-sim-results-panel h3 {
    font-size: 0.95rem;
    font-weight: 700;
    color: #e6f1ff;
    margin-bottom: 20px;
    padding-bottom: 12px;
    border-bottom: 1px solid #1f2d3d;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-input-group {
    margin-bottom: 20px;
}

.aero-sim-decision-label {
    display: block;
    font-size: 0.78rem;
    font-weight: 700;
    color: #c9d1d9;
    margin-bottom: 8px;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-slider-row {
    display: flex;
    align-items: center;
    gap: 12px;
}

.aero-sim-slider {
    flex: 1;
    accent-color: #00b4d8;
    cursor: pointer;
    background: transparent;
}

.aero-sim-slider-val {
    font-weight: 800;
    color: #00b4d8;
    font-size: 0.95rem;
    min-width: 58px;
    text-align: right;
    font-family: 'Courier New', ui-monospace, SFMono-Regular, monospace;
}

.aero-sim-select {
    width: 100%;
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #c9d1d9;
    border-radius: 6px;
    padding: 10px 12px;
    font-size: 0.82rem;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-select:focus {
    border-color: #00b4d8;
    outline: none;
    box-shadow: 0 0 0 2px rgba(0,180,216,0.2);
}

/* Options ignore inheritance in most browsers — set colors explicitly for the dark theme */
.aero-sim-select option {
    background: #0a0f1e;
    color: #c9d1d9;
}

.aero-sim-number-input {
    width: 100%;
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e6f1ff;
    border-radius: 6px;
    padding: 10px 12px;
    font-size: 1rem;
    font-weight: 700;
    font-family: 'Courier New', monospace;
}

.aero-sim-number-input:focus {
    border-color: #00b4d8;
    outline: none;
    box-shadow: 0 0 0 2px rgba(0,180,216,0.2);
}

.aero-sim-ped-badge {
    font-size: 0.68rem;
    color: #9aa4b2;
    margin-top: 4px;
    padding: 3px 8px;
    background: rgba(0,180,216,0.06);
    border: 1px solid #1f2d3d;
    border-radius: 4px;
    display: inline-block;
}

.aero-sim-hint-text {
    font-size: 0.68rem;
    color: #8b949e;
    margin-top: 4px;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-action-buttons {
    display: flex;
    gap: 10px;
    margin-top: 24px;
    flex-wrap: wrap;
}

.aero-sim-submit-btn {
    flex: 1;
    background: linear-gradient(135deg, #0077b6, #00b4d8) !important;
    border: none !important;
    font-weight: 700;
    padding: 13px 18px;
    border-radius: 8px;
    font-size: 0.88rem;
    color: #ffffff !important;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    font-family: -apple-system, 'Inter', sans-serif;
    transition: opacity 0.2s ease;
}

.aero-sim-submit-btn:hover {
    opacity: 0.9;
}

.aero-sim-results-log {
    font-size: 0.84rem;
    color: #c9d1d9;
    line-height: 1.9;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-hint-box {
    background: rgba(245,158,11,0.08);
    border: 1px solid rgba(245,158,11,0.3);
    border-radius: 8px;
    padding: 12px 16px;
    margin-top: 16px;
    font-size: 0.82rem;
    color: #f59e0b;
    font-weight: 600;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-history-section {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 24px;
}

.aero-sim-history-section h3 {
    font-size: 0.95rem;
    font-weight: 700;
    color: #e6f1ff;
    margin-bottom: 16px;
    font-family: -apple-system, 'Inter', sans-serif;
}

.aero-sim-history-section .table {
    color: #c9d1d9;
    font-size: 0.8rem;
    background: transparent;
}

.aero-sim-history-section .table thead th {
    color: #9aa4b2;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    background: #0d1421;
    border-color: #1f2d3d;
}

.aero-sim-history-section .table tbody td {
    color: #c9d1d9;
    border-color: #1a2332;
}

.aero-sim-history-section .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(0,180,216,0.03);
}

.aero-sim-chart-section {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 12px;
    padding: 24px;
}

@media (max-width: 768px) {
    .aero-sim-container { padding: 14px; }
    .aero-sim-decisions-grid { grid-template-columns: 1fr; }
    .aero-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .aero-sim-route-panel { flex-direction: column; }
    .aero-sim-header h1 { font-size: 1.2rem; }
}

