(function() {
    'use strict';

    class AeroHondurasAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Precio Correcto';
            this.version = '1.1.0';

            this.ROUTES = {
                high:  { basePax: 127500, baseAsp: 65, ped: -2.0, shareRev: 0.38, label: 'TGU-SLV, SPS-SLV' },
                med:   { basePax: 130000, baseAsp: 57, ped: -1.4, shareRev: 0.38, label: 'TGU-SPS, SPS-MGA, Others' },
                low:   { basePax:  58500, baseAsp: 72, ped: -0.7, shareRev: 0.24, label: 'TGU-GUA, TGU-BZE' }
            };

            this.BASE_Q_REVENUE = 22350000;
            this.BASE_Q_EBITDA  = 4675000;
            this.BASE_Q_PAX     = 310000;
            this.BASE_ASP       = 72;
            this.BASE_LOAD      = 72;
            this.COST_PER_PAX   = 48;
            this.BASELINE_ANNUAL_REVENUE = 89400000;

            // Round scenario text/names now live in getTranslations() (keys brief1..4 / rname1..4)
            // so they follow the same reliable language resolution as every other string.
            // This array is kept only to drive round count / index bounds.
            this.ROUNDS = [{ id: 1 }, { id: 2 }, { id: 3 }, { id: 4 }];
        }

        // Robust language read: .language first (canonical), then .currentLanguage, then <html lang>, then 'en'.
        _lang() {
            var m = window.mySimulation || {};
            var htmlLang = (document.documentElement && document.documentElement.getAttribute)
                ? document.documentElement.getAttribute('lang') : null;
            return m.language || m.currentLanguage || htmlLang || 'en';
        }

        _t(key) {
            return (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t(key) : key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    qRevenue: 22350000,
                    qEbitda: 4675000,
                    qPax: 310000,
                    asp: 72,
                    loadFactor: 72,
                    marginPerPax: 15.10,
                    revenueHistory: [],
                    ebitdaHistory: [],
                    aspHistory: [],
                    loadHistory: [],
                    cumulativeRevenueImpact: 0,
                    flyBudgetImpactApplied: false,
                    pricingModelChosen: 0,
                    strategyChosen: 0
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    highElasticPrice: 0,
                    medElasticPrice: 0,
                    lowElasticPrice: 0,
                    pricingModel: 1,
                    businessPremium: 20,
                    advanceDiscount: 15,
                    responseStrategy: 1,
                    tguGuaAdjust: 0,
                    targetAsp: 72,
                    capacityShift: 10,
                    rmInvestment: 500
                };
            }
            this._updateBriefing(state);
            this._setupSliderListeners();
        }

        _setupSliderListeners() {
            var sliders = [
                { id: 'highElasticPrice', display: 'highElasticVal', suffix: '%' },
                { id: 'medElasticPrice',  display: 'medElasticVal',  suffix: '%' },
                { id: 'lowElasticPrice',  display: 'lowElasticVal',  suffix: '%' },
                { id: 'businessPremium',  display: 'bizPremVal',     suffix: '%' },
                { id: 'advanceDiscount',  display: 'advDiscVal',     suffix: '%' },
                { id: 'tguGuaAdjust',     display: 'tguGuaVal',      suffix: '%' },
                { id: 'capacityShift',    display: 'capShiftVal',    suffix: '%' },
                { id: 'rmInvestment',     display: 'rmInvestVal',    prefix: '$', suffix: 'K' }
            ];
            sliders.forEach(function(s) {
                var el = document.getElementById(s.id);
                var disp = document.getElementById(s.display);
                if (el && disp) {
                    el.addEventListener('input', function() {
                        var prefix = s.prefix || '';
                        var suffix = s.suffix || '';
                        disp.textContent = prefix + el.value + suffix;
                    });
                }
            });
        }

        _updateBriefing(state) {
            var cp = (state && state.currentPeriod) || 1;
            var max = this.ROUNDS.length;

            var briefEl = document.getElementById('briefingText');
            var roundNameEl = document.getElementById('roundName');
            var panels = ['round1Controls', 'round2Controls', 'round3Controls', 'round4Controls'];
            var routePanel = document.getElementById('routePanel');
            var submitBtn = document.getElementById('nextPeriodBtn');

            // Simulation complete: hide all decision controls, disable submit, show a closing brief.
            if (cp > max) {
                if (briefEl) briefEl.innerHTML = this._t('sim_complete_msg');
                if (roundNameEl) roundNameEl.textContent = this._t('sim_complete_tag');
                panels.forEach(function(pId) {
                    var panel = document.getElementById(pId);
                    if (panel) panel.style.display = 'none';
                });
                if (routePanel) routePanel.style.display = 'none';
                if (submitBtn) { submitBtn.style.display = 'none'; submitBtn.disabled = true; }
                return;
            }

            var idx = Math.min(cp - 1, max - 1);

            if (briefEl) briefEl.innerHTML = this._t('brief' + (idx + 1));
            if (roundNameEl) roundNameEl.textContent = this._t('rname' + (idx + 1));

            panels.forEach(function(pId, i) {
                var panel = document.getElementById(pId);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            });

            if (routePanel) routePanel.style.display = (idx === 0) ? 'flex' : 'none';
            if (submitBtn) { submitBtn.style.display = ''; submitBtn.disabled = false; }
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;

            // Guard: no decisions accepted once the simulation is complete.
            if (period > this.ROUNDS.length) return false;

            this._updateBriefing(window.mySimulation.state);

            if (period === 1) {
                var hep = document.getElementById('highElasticPrice');
                var mep = document.getElementById('medElasticPrice');
                var lep = document.getElementById('lowElasticPrice');
                if (hep) decisions.highElasticPrice = parseInt(hep.value);
                if (mep) decisions.medElasticPrice = parseInt(mep.value);
                if (lep) decisions.lowElasticPrice = parseInt(lep.value);
            } else if (period === 2) {
                var pm = document.getElementById('pricingModel');
                var bp = document.getElementById('businessPremium');
                var ad = document.getElementById('advanceDiscount');
                if (pm) decisions.pricingModel = parseInt(pm.value);
                if (bp) decisions.businessPremium = parseInt(bp.value);
                if (ad) decisions.advanceDiscount = parseInt(ad.value);
            } else if (period === 3) {
                var rs = document.getElementById('responseStrategy');
                var tg = document.getElementById('tguGuaAdjust');
                if (rs) decisions.responseStrategy = parseInt(rs.value);
                if (tg) decisions.tguGuaAdjust = parseInt(tg.value);
            } else if (period === 4) {
                var ta = document.getElementById('targetAsp');
                var cs = document.getElementById('capacityShift');
                var ri = document.getElementById('rmInvestment');
                if (ta) decisions.targetAsp = parseFloat(ta.value);
                if (cs) decisions.capacityShift = parseInt(cs.value);
                if (ri) decisions.rmInvestment = parseInt(ri.value);

                if (!Number.isFinite(decisions.targetAsp) || decisions.targetAsp < 40 || decisions.targetAsp > 120) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('asp_warning'), 'warning'
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = {};

            if (period === 1) {
                var highPriceChg = d.highElasticPrice / 100;
                var medPriceChg = d.medElasticPrice / 100;
                var lowPriceChg = d.lowElasticPrice / 100;

                var highDemandChg = 1 + (this.ROUTES.high.ped * highPriceChg);
                var medDemandChg = 1 + (this.ROUTES.med.ped * medPriceChg);
                var lowDemandChg = 1 + (this.ROUTES.low.ped * lowPriceChg);

                highDemandChg = Math.max(0.3, highDemandChg);
                medDemandChg = Math.max(0.4, medDemandChg);
                lowDemandChg = Math.max(0.5, lowDemandChg);

                var flyBudgetDemandHit = 0.70;
                var highPax = Math.round(this.ROUTES.high.basePax * highDemandChg * flyBudgetDemandHit);
                var medPax = Math.round(this.ROUTES.med.basePax * medDemandChg);
                var lowPax = Math.round(this.ROUTES.low.basePax * lowDemandChg);

                var highRev = highPax * this.ROUTES.high.baseAsp * (1 + highPriceChg);
                var medRev = medPax * this.ROUTES.med.baseAsp * (1 + medPriceChg);
                var lowRev = lowPax * this.ROUTES.low.baseAsp * (1 + lowPriceChg);

                var totalPax = highPax + medPax + lowPax;
                var totalRev = highRev + medRev + lowRev;
                var totalCost = totalPax * this.COST_PER_PAX;
                var ebitda = totalRev - totalCost;
                var asp = totalPax > 0 ? totalRev / totalPax : 0;
                var loadFactor = Math.min(95, Math.max(40, 72 * (totalPax / this.BASE_Q_PAX)));
                var marginPerPax = totalPax > 0 ? (totalRev - totalCost) / totalPax : 0;

                ds.qRevenue = Math.round(totalRev);
                ds.qEbitda = Math.round(ebitda);
                ds.qPax = totalPax;
                ds.asp = Math.round(asp * 100) / 100;
                ds.loadFactor = Math.round(loadFactor * 10) / 10;
                ds.marginPerPax = Math.round(marginPerPax * 100) / 100;

                results = {
                    period: period,
                    qRevenue: ds.qRevenue,
                    qEbitda: ds.qEbitda,
                    passengers: totalPax,
                    asp: ds.asp,
                    loadFactor: ds.loadFactor,
                    marginPerPax: ds.marginPerPax,
                    highPax: highPax,
                    medPax: medPax,
                    lowPax: lowPax
                };

            } else if (period === 2) {
                var modelMultiplier = 1.0;
                var modelCost = 0;
                if (d.pricingModel === 2) { modelMultiplier = 1.04; modelCost = 150000; }
                if (d.pricingModel === 3) { modelMultiplier = 1.09; modelCost = 450000; }

                var bizShare = 0.15;
                var advShare = 0.35;
                var regularShare = 0.25;
                var discountShare = 0.25;

                var baseRev = ds.qRevenue;
                var bizRevFactor = 1 + (d.businessPremium / 100);
                var advRevFactor = 1 - (d.advanceDiscount / 100);

                var segmentedRev = baseRev * (
                    bizShare * bizRevFactor +
                    advShare * advRevFactor +
                    regularShare * 1.0 +
                    discountShare * 0.80
                ) * modelMultiplier;

                var newPax = Math.round(ds.qPax * (1 + (d.advanceDiscount / 100) * 0.15));
                var totalRev2 = Math.round(segmentedRev);
                var totalCost2 = (newPax * this.COST_PER_PAX) + modelCost;
                var ebitda2 = totalRev2 - totalCost2;
                var asp2 = newPax > 0 ? totalRev2 / newPax : 0;
                var loadFactor2 = Math.min(95, Math.max(40, ds.loadFactor * (newPax / ds.qPax)));

                ds.qRevenue = totalRev2;
                ds.qEbitda = Math.round(ebitda2);
                ds.qPax = newPax;
                ds.asp = Math.round(asp2 * 100) / 100;
                ds.loadFactor = Math.round(loadFactor2 * 10) / 10;
                ds.marginPerPax = newPax > 0 ? Math.round(((totalRev2 - totalCost2) / newPax) * 100) / 100 : 0;
                ds.pricingModelChosen = d.pricingModel;

                results = {
                    period: period,
                    qRevenue: ds.qRevenue,
                    qEbitda: ds.qEbitda,
                    passengers: newPax,
                    asp: ds.asp,
                    loadFactor: ds.loadFactor,
                    marginPerPax: ds.marginPerPax,
                    pricingModel: d.pricingModel,
                    modelCost: modelCost
                };

            } else if (period === 3) {
                var strategy = d.responseStrategy;
                var tguGuaPriceChg = d.tguGuaAdjust / 100;

                var baseRevQ = ds.qRevenue;
                var basePaxQ = ds.qPax;

                var lowRouteShare = 0.24;
                var lowRouteRev = baseRevQ * lowRouteShare;
                var lowRoutePax = Math.round(basePaxQ * lowRouteShare);

                var flyBudgetLoss = 0.30;
                var lowRoutePaxPost = Math.round(lowRoutePax * (1 - flyBudgetLoss));
                var lowRouteNewAsp = this.ROUTES.low.baseAsp * (1 + tguGuaPriceChg);

                var strategyRevMult = 1.0;
                var strategyPaxMult = 1.0;
                var strategyCost = 0;

                if (strategy === 1) {
                    strategyRevMult = 0.82;
                    strategyPaxMult = 1.12;
                    strategyCost = 0;
                } else if (strategy === 2) {
                    strategyRevMult = 0.94;
                    strategyPaxMult = 0.88;
                    strategyCost = 0;
                } else if (strategy === 3) {
                    strategyRevMult = 1.02;
                    strategyPaxMult = 0.95;
                    strategyCost = 350000;
                } else if (strategy === 4) {
                    strategyRevMult = 0.96;
                    strategyPaxMult = 1.05;
                    strategyCost = 200000;
                }

                var otherRev = baseRevQ * (1 - lowRouteShare);
                var otherPax = basePaxQ - lowRoutePax;
                var newLowRev = lowRoutePaxPost * lowRouteNewAsp * strategyRevMult;
                var newOtherRev = otherRev * (strategyRevMult * 0.5 + 0.5);
                var newOtherPax = Math.round(otherPax * strategyPaxMult);

                var totalRev3 = Math.round(newLowRev + newOtherRev);
                var totalPax3 = lowRoutePaxPost + newOtherPax;
                var totalCost3 = (totalPax3 * this.COST_PER_PAX) + strategyCost;
                var ebitda3 = totalRev3 - totalCost3;
                var asp3 = totalPax3 > 0 ? totalRev3 / totalPax3 : 0;
                var loadFactor3 = Math.min(95, Math.max(40, ds.loadFactor * (totalPax3 / basePaxQ)));

                ds.qRevenue = totalRev3;
                ds.qEbitda = Math.round(ebitda3);
                ds.qPax = totalPax3;
                ds.asp = Math.round(asp3 * 100) / 100;
                ds.loadFactor = Math.round(loadFactor3 * 10) / 10;
                ds.marginPerPax = totalPax3 > 0 ? Math.round(((totalRev3 - totalCost3) / totalPax3) * 100) / 100 : 0;
                ds.strategyChosen = strategy;

                results = {
                    period: period,
                    qRevenue: ds.qRevenue,
                    qEbitda: ds.qEbitda,
                    passengers: totalPax3,
                    asp: ds.asp,
                    loadFactor: ds.loadFactor,
                    marginPerPax: ds.marginPerPax,
                    strategy: strategy,
                    strategyCost: strategyCost
                };

            } else if (period === 4) {
                var targetAsp = d.targetAsp;
                var capShift = d.capacityShift / 100;
                var rmInvest = d.rmInvestment * 1000;

                var rmYieldBoost = Math.min(0.08, rmInvest / 25000000);

                var aspRatio = targetAsp / ds.asp;
                var avgPed = -1.4;
                var paxImpact = 1 + (avgPed * (aspRatio - 1));
                paxImpact = Math.max(0.5, Math.min(1.3, paxImpact));

                var protectedRouteYield = 1 + (capShift * 0.6);
                var competitiveRouteLoss = 1 - (capShift * 0.3);

                var protectedShare = 0.24 + capShift;
                var competitiveShare = 1 - protectedShare;

                var newPax4 = Math.round(ds.qPax * paxImpact);
                var revFromProtected = newPax4 * protectedShare * targetAsp * protectedRouteYield;
                var revFromCompetitive = newPax4 * competitiveShare * targetAsp * competitiveRouteLoss * 0.85;
                var totalRev4 = Math.round((revFromProtected + revFromCompetitive) * (1 + rmYieldBoost));
                var totalCost4 = (newPax4 * this.COST_PER_PAX) + rmInvest;
                var ebitda4 = totalRev4 - totalCost4;
                var asp4 = newPax4 > 0 ? totalRev4 / newPax4 : 0;
                var loadFactor4 = Math.min(95, Math.max(40, ds.loadFactor * (newPax4 / ds.qPax)));

                var annualRevProjected = totalRev4 * 4;
                var annualEbitdaProjected = ebitda4 * 4;

                ds.qRevenue = totalRev4;
                ds.qEbitda = Math.round(ebitda4);
                ds.qPax = newPax4;
                ds.asp = Math.round(asp4 * 100) / 100;
                ds.loadFactor = Math.round(loadFactor4 * 10) / 10;
                ds.marginPerPax = newPax4 > 0 ? Math.round(((totalRev4 - totalCost4) / newPax4) * 100) / 100 : 0;

                results = {
                    period: period,
                    qRevenue: ds.qRevenue,
                    qEbitda: ds.qEbitda,
                    passengers: newPax4,
                    asp: ds.asp,
                    loadFactor: ds.loadFactor,
                    marginPerPax: ds.marginPerPax,
                    annualRevProjected: Math.round(annualRevProjected),
                    annualEbitdaProjected: Math.round(annualEbitdaProjected),
                    rmInvestment: rmInvest,
                    capacityShift: d.capacityShift
                };
            }

            ds.revenueHistory.push(ds.qRevenue);
            ds.ebitdaHistory.push(ds.qEbitda);
            ds.aspHistory.push(ds.asp);
            ds.loadHistory.push(ds.loadFactor);

            var resultsPanel = document.getElementById('resultsPanel');
            var resultsLog = document.getElementById('resultsLog');
            if (resultsPanel) resultsPanel.style.display = 'block';
            if (resultsLog) {
                var revStr = '$' + (ds.qRevenue / 1000000).toFixed(1) + 'M';
                var ebitStr = '$' + (ds.qEbitda / 1000000).toFixed(1) + 'M';
                var ebitdaMargin = ds.qRevenue > 0 ? ((ds.qEbitda / ds.qRevenue) * 100).toFixed(1) : '0.0';
                resultsLog.innerHTML = '<strong>' + window.mySimulation.t('result_revenue') + ':</strong> ' + revStr +
                    '<br><strong>' + window.mySimulation.t('result_ebitda') + ':</strong> ' + ebitStr + ' (' + ebitdaMargin + '%)' +
                    '<br><strong>' + window.mySimulation.t('result_asp') + ':</strong> $' + ds.asp.toFixed(2) +
                    '<br><strong>' + window.mySimulation.t('result_pax') + ':</strong> ' + ds.qPax.toLocaleString() +
                    '<br><strong>' + window.mySimulation.t('result_load') + ':</strong> ' + ds.loadFactor + '%' +
                    '<br><strong>' + window.mySimulation.t('result_margin') + ':</strong> $' + ds.marginPerPax.toFixed(2) + '/pax';
            }

            var self = this;
            // Pass the REAL framework state (per USF guide §12) so the post-advance briefing
            // reflects the framework's own currentPeriod increment (and reaches the completion
            // branch after the final round instead of re-showing round 4).
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            return results;
        }

