        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = this._t.bind(this);

            // Grade on the FINAL-quarter run-rate (annualised), matching the board's
            // "vs. the $89.4M baseline" framing and Round 4's own annualRevProjected.
            // (Previously this averaged all four quarters, which included the structural
            // FlyBudget shock in R1-R3, so no achievable play could clear the thresholds.)
            var last = history[history.length - 1].results || {};
            var lastRev = last.qRevenue || 0;
            var lastEbitda = last.qEbitda || 0;
            var finalAsp = last.asp || 0;

            var annualRevProj = lastRev * 4;
            var annualEbitdaProj = lastEbitda * 4;
            var ebitdaMargin = lastRev > 0 ? (lastEbitda / lastRev * 100) : (lastEbitda < 0 ? -100 : 0);
            var retention = this.BASELINE_ANNUAL_REVENUE > 0 ? (annualRevProj / this.BASELINE_ANNUAL_REVENUE) : 0;

            var performance;
            var insights = [];

            if (ebitdaMargin < 0) {
                performance = t('perf_unsustainable');
                insights.push(t('insight_loss'));
            } else if (retention >= 0.82 && ebitdaMargin >= 22 && finalAsp >= 65) {
                performance = t('perf_excellent');
                insights.push(t('insight_excellent'));
            } else if (retention >= 0.72 && ebitdaMargin >= 18) {
                performance = t('perf_verygood');
                insights.push(t('insight_verygood'));
            } else if (retention >= 0.60 && ebitdaMargin >= 12) {
                performance = t('perf_good');
                insights.push(t('insight_good'));
            } else {
                performance = t('perf_needs');
                if (retention < 0.60) insights.push(t('insight_low_revenue'));
            }

            // Additional teaching signals (never leave the debrief empty).
            if (finalAsp < 50) insights.push(t('insight_asp_danger'));
            if (ebitdaMargin >= 40 && retention < 0.60) insights.push(t('insight_overpriced'));

            return {
                annualRevProjected: Math.round(annualRevProj),
                annualEbitdaProjected: Math.round(annualEbitdaProj),
                ebitdaMargin: Math.round(ebitdaMargin * 10) / 10,
                finalAsp: finalAsp,
                revenueRetentionPct: Math.round(retention * 1000) / 10,
                performance: performance,
                insights: insights
            };
        }

